# return alarm name if alarm is selected

if 'name' not in value.keys():
	return 'No alarm selected'
else:
	return value['name']

# if 'udtAlarm' param is empty, then this is not a UDT alarm instance (don't display this container)

if len(self.view.params.udtAlarm.keys()) == 0:
	return False
else:
	return True

# if 'alarm' param is empty, no alarm selected (don't display buttons and overridden info)

if len(value.items()) == 0:
	return False
else:
	return True

# if 'alarm' param is empty (no alarm selected), don't display this

currAlarm = value['alarm']

if len(currAlarm.items()) == 0:
	return False
else:
	# if enabledProps does not contain any main alarm props, then main table will not
	# have any configurable properties; in this case, do not display top bar
	mainProps = value['mainProps']

	# have at least one main prop enabled
	if len(mainProps) > 0:
		return True
	else:
		return False

# if 'alarm' param is empty (no alarm selected), don't display this

currAlarm = value['alarm']

if len(currAlarm.items()) == 0:
	return False
else:
	# if enabledProps does not contain any alarm mode settings props, then alarm mode settings
	# table will not have any configurable properties; in this case, do not display top bar
	alarmModeProps = value['alarmModeProps']

	# have at least one main prop enabled
	if len(alarmModeProps) > 0:
		return True
	else:
		return False

# also, utilize enabledProps list to determine which properties should be enabled

currAlarm = value['alarm']
enabledProps = value['enabledProps']

# if 'mode' is not in the alarm object, then it must be set to the default 'Equal'

if 'mode' not in currAlarm.keys():
	mode = 'Equal'
else:
	mode = currAlarm['mode']

# the properties to be displayed in this section depends on the mode of the alarm;
# each of the six startingData objects contains info about the properties for this
# section; find the correct startingData based on the mode

if mode in ['Equal','Not Equal']:
	data = self.custom.startingData0
elif mode in ['Above Setpoint','Below Setpoint']:
	data = self.custom.startingData1
elif mode in ['Between Setpoints','Outside Setpoints']:
	data = self.custom.startingData2
elif mode in ['Out of range','Bad Quality','Any Change']:
	data = self.custom.startingData3
elif mode == 'Bit State':
	data = self.custom.startingData4
else:
	# only remaining option is 'On Condition'
	data = self.custom.startingData5 

propBindingClass = "<type 'com.inductiveautomation.perspective.gateway.script.DotReferenceJythonMap'>"

tableData = []
for startingRow in data:
	row = dict(startingRow)
	underlyingName = row['underlyingName']

	# only display this property in the table if it is enabled or if the enabledProps is empty 
	# (in that case, show all props)
	if underlyingName in enabledProps or len(enabledProps) == 0:
		propName = row['propName']
		# if the underlying name of the property does not exist in the 'alarm' object, then this 
		# property must be set to the default value
		if underlyingName not in currAlarm.keys():
			row['value'] = startingRow['default']
			row['propName'] = {"value": propName, "editable": False, "style": {"paddingLeft":'8px',"classes": ""},"align": "center","justify": "left"}
		else:
			# underlying name of the property does exist in the 'alarm' object, so figure out if the
			# property has a binding or not by looking at the type of the object
			if str(type(currAlarm[underlyingName])) == propBindingClass:
				# property has a binding, set dropdown to 0 (don't display dropdown if property is bound),
				# set bindType (tag or expression), make property name bold to denote the property is bound
				row['value'] = currAlarm[underlyingName]['value']
				row['dropdown'] = 0
				row['bindType'] = currAlarm[underlyingName]['bindType']
				row['propName'] = {"value": propName, "editable": False, "style": {"fontWeight": "bold","paddingLeft":'8px',"classes": ""},"align": "center","justify": "left"}
			else:
				# property does not have a binding
				row['value'] = currAlarm[underlyingName]
				row['propName'] = {"value": propName, "editable": False, "style": {"paddingLeft":'8px',"classes": ""},"align": "center","justify": "left"}

		tableData.append(row)

return tableData

